    <label className="inline-flex h-9 items-center gap-1.5 px-2 text-xs text-[#323647]"><RotevoTablerIcon name="folder" size={16}/><select aria-label="Agrupar conteúdos por" value={listGroupMode} onChange={e=>{setListGroupMode(e.target.value as "client"|"project"|"flat");setCollapsedListGroups({});}} className="max-w-[115px] cursor-pointer bg-transparent text-xs outline-none"><option value="client">Por cliente</option><option value="project">Por projeto</option><option value="flat">Lista única</option></select></label>
